#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for square matrix multiplication C = A * B using shared memory and tiling
__global__ void square_matrix_multiplication_kernel(const float* A, const float* B, float* C, int N) {
    const int TILE_SIZE = 32; 

    // Shared memory for tiles of A and B, with padding to avoid bank conflicts
    __shared__ float sA[TILE_SIZE][TILE_SIZE + 1]; // +1 for padding on columns for row-major access
    __shared__ float sB_transposed[TILE_SIZE + 1][TILE_SIZE]; // +1 for padding on rows for column-major access (of original B)

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float C_value = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tiles from global memory to shared memory
        // For A:
        int A_row_global = row;
        int A_col_global = t * TILE_SIZE + threadIdx.x;
        if (A_row_global < N && A_col_global < N) {
            sA[threadIdx.y][threadIdx.x] = A[A_row_global * N + A_col_global];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; 
        }

        // For B (transposed):
        // Each thread (threadIdx.x, threadIdx.y) loads one element of B,
        // and stores it into sB_transposed in a transposed fashion for efficient access later.
        // B[k_global][col_global] is loaded by thread (threadIdx.x, threadIdx.y)
        // B_row_global (k_global) is the 'k' dimension which iterates during the outer loop
        // B_col_global (col_global) is the 'col' dimension, constant for C[row][col]
        int B_row_global = t * TILE_SIZE + threadIdx.y; // This maps to 'k' for B
        int B_col_global = col; // This maps to 'col' for B

        if (B_row_global < N && B_col_global < N) {
            // Store B[k][col] into sB_transposed[col_in_tile][k_in_tile]
            sB_transposed[threadIdx.x][threadIdx.y] = B[B_row_global * N + B_col_global];
        } else {
            sB_transposed[threadIdx.x][threadIdx.y] = 0.0f;
        }

        __syncthreads();

        // Perform matrix multiplication on the tiles in shared memory
        // C_value += sA[row_in_tile][k_in_tile] * sB_transposed[col_in_tile][k_in_tile]
        // Here, threadIdx.y is row_in_tile for sA, threadIdx.x is col_in_tile for sB_transposed
        // 'i' is k_in_tile
        for (int i = 0; i < TILE_SIZE; ++i) {
            C_value += sA[threadIdx.y][i] * sB_transposed[threadIdx.x][i]; 
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = C_value;
    }
